--
-- Table structure for table `households`
--

DROP TABLE IF EXISTS `households`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `households` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `household_code` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'mã hộ , 1 hộ có nhiều người trong nhà í',
  `school_year` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `head_first_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `head_last_name` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `province_code` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Mã Tỉnh/Thành phố',
  `commune_code` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Mã Xã/Phường',
  `village_code` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Mã thôn/xóm',
  `address` text COLLATE utf8mb4_unicode_ci,
  `residence_type` enum('THUONG_TRU','TAM_TRU','KHAC') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'THUONG_TRU',
  `residence_status` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `import_log_id` bigint unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_households_school_year_code` (`school_year`,`household_code`),
  KEY `households_import_log_id_foreign` (`import_log_id`),
  KEY `households_household_code_index` (`household_code`),
  KEY `households_commune_code_foreign` (`commune_code`),
  KEY `idx_household_location` (`province_code`,`commune_code`),
  KEY `idx_household_village` (`village_code`),
  KEY `households_school_year_household_code_index` (`school_year`,`household_code`),
  CONSTRAINT `households_commune_code_foreign` FOREIGN KEY (`commune_code`) REFERENCES `communes` (`code`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `households_import_log_id_foreign` FOREIGN KEY (`import_log_id`) REFERENCES `import_logs` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `households_province_code_foreign` FOREIGN KEY (`province_code`) REFERENCES `provinces` (`code`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `households_village_code_foreign` FOREIGN KEY (`village_code`) REFERENCES `villages` (`code`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=290 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

