--
-- Table structure for table `person_disabilities`
--

DROP TABLE IF EXISTS `person_disabilities`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `person_disabilities` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `person_id` bigint unsigned NOT NULL,
  `mobility_disability` tinyint(1) NOT NULL DEFAULT '0',
  `hearing_speech_disability` tinyint(1) NOT NULL DEFAULT '0',
  `visual_disability` tinyint(1) NOT NULL DEFAULT '0',
  `mental_disability` tinyint(1) NOT NULL DEFAULT '0',
  `intellectual_disability` tinyint(1) NOT NULL DEFAULT '0',
  `learning_disability` tinyint(1) NOT NULL DEFAULT '0',
  `autism` tinyint(1) NOT NULL DEFAULT '0',
  `other_disability` tinyint(1) NOT NULL DEFAULT '0',
  `has_disability_cert` tinyint(1) NOT NULL DEFAULT '0',
  `can_study` tinyint(1) DEFAULT NULL COMMENT 'Có khả năng học tập hay không',
  `special_circumstance` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `special_circumstance_detail` text COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `person_disabilities_person_id_unique` (`person_id`),
  CONSTRAINT `person_disabilities_person_id_foreign` FOREIGN KEY (`person_id`) REFERENCES `persons` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1137 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

