CREATE TABLE `person_educations` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `person_id` bigint unsigned NOT NULL,
  `import_log_id` bigint unsigned DEFAULT NULL,
  `school_year` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '2025-2026 năm học',
  `academic_block` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `current_class` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `school_code` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `graduation_level` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `is_complementary` tinyint(1) NOT NULL DEFAULT '0',
  `graduation_year` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '2022-2023',
  `vocational_grad_level` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `vocational_grad_year` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '2022-2023',
  `finished_class` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `finished_year` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `dropped_class` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `dropped_year` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `literacy_current_class` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Đang học lớp XMC nào (VD: Lớp 1, Lớp 2...)',
  `literacy_completed_class` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Hoàn thành lớp XMC nào',
  `literacy_relapse_level` tinyint DEFAULT NULL COMMENT 'Tái mù chữ mức: 1 = Mức 1, 2 = Mức 2',
  `learning_capacity` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Năng lực học tập (Khả năng tiếp thu/Khuyết tật)',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_person_school_year` (`person_id`,`school_year`),
  KEY `person_educations_import_log_id_foreign` (`import_log_id`),
  KEY `idx_education_school_year` (`school_year`),
  KEY `idx_education_school_code` (`school_code`),
  CONSTRAINT `person_educations_import_log_id_foreign` FOREIGN KEY (`import_log_id`) REFERENCES `import_logs` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `person_educations_person_id_foreign` FOREIGN KEY (`person_id`) REFERENCES `persons` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `person_educations_school_code_foreign` FOREIGN KEY (`school_code`) REFERENCES `schools` (`code`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=126 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
